{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_and_handles_empty_groups():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 1, False)] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_log_skips_and_trims_and_parses_flags():
    lines = ["\n", "   # comment, with, commas", "  a  ,  3 , 1 ", "b, -2, 0", "c, 4,  ", " \t "]
    assert parse_transcript_log(lines) == [
        event("a", 3, True), event("b", -2, False), event("c", 4, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,nope,1", "a,1,yes"])
def test_parse_log_errors_identify_original_line(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # comment", "ok,1,1", bad_line])


def test_dedupe_keeps_last_duplicate_not_latest_day_and_sorts():
    events = [event("b", 5, True), event("a", 1, True), event("b", 1, False), event("c", 0, None)]
    assert dedupe_transcripts(events) == [events[3], events[1], events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_gaps_and_outside():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts(events, 2, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_uses_calendar_days_weighting_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 4, False), event("c", 4, False)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "b": [event("b", 1, True)],
              "empty": [], "a": [event("a", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["b", "z", "a"]
    assert top_flagged_groups(groups, 1) == ["b"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_includes_empty_and_sorts_keys():
    groups = {"z": [], "b": [event("b", 1, True), event("c", 1, None)], "a": []}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": None, "b": 0.5, "z": None}


def test_longest_flag_streak_resets_on_zero_and_negative():
    assert longest_flag_streak([1, 2, 0, 1, -1, 2, 3, 4]) == 3
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0
